window.DEEPDIVE=window.DEEPDIVE||{};window.DEEPDIVE["clip"]={"title":"CLIP：用图文对比把两种模态对齐到同一空间","subtitle":"从双编码器、归一化相似度矩阵和对称交叉熵，到零样本分类、检索、组合关系与偏差边界。","thesis":"CLIP 用独立图像和文本编码器把匹配图文拉近、不匹配组合推远，学习可检索的开放词汇空间。它的扩展性来自大规模弱配对和批内负样本；但全局相似度主要证明“这张图与这段话在数据分布中常配对”，<b>不自动证明对象关系、数量、否定、真实性或公平</b>。","quality":{"contractVersion":2,"examples":[{"section":3,"evidence":{"setup":"沿用上一节 logits [[8,2],[3,7]]","rule":"按行、按列各算一次","steps":"e⁸/(e⁸+e²)","interpretation":"两个行概率越接近 1，图到文损失越小"}}],"formulas":[{"id":"clip-dual-encoder-normalization","section":1,"formulaIndex":1,"symbols":[{"name":"v","meaning":"归一化后的图像向量","evidence":"vᵢ 是归一化后的图像向量"},{"name":"i","meaning":"batch 中图像样本的编号","evidence":"Iᵢ 是第 i 张图像"},{"name":"f","meaning":"带 img 或 txt 下标的模态编码器","evidence":"f_img 是图像编码器"},{"name":"I","meaning":"输入图像样本","evidence":"Iᵢ 是第 i 张图像"},{"name":"t","meaning":"归一化后的文本向量","evidence":"tⱼ 是归一化后的文本向量"},{"name":"j","meaning":"batch 中文本样本的编号","evidence":"Tⱼ 是第 j 段文本"},{"name":"T","meaning":"输入文本样本","evidence":"Tⱼ 是第 j 段文本"},{"name":"‖","meaning":"计算向量 L2 长度的范数符号","evidence":"双竖线 ‖·‖ 表示向量长度"}]},{"id":"clip-pairwise-logits","section":2,"formulaIndex":1,"symbols":[{"name":"S","meaning":"图文候选对的 softmax 前匹配分数矩阵","evidence":"Sᵢⱼ 是第 i 张图与第 j 段文本送入 softmax 前的匹配分数"},{"name":"i","meaning":"图像在 batch 中的行编号","evidence":"第 i 张图"},{"name":"j","meaning":"文本在 batch 中的列编号","evidence":"第 j 段文本"},{"name":"v","meaning":"单位长度的图像向量","evidence":"vᵢ 和 tⱼ 是单位长度图像、文本向量"},{"name":"t","meaning":"单位长度的文本向量","evidence":"vᵢ 和 tⱼ 是单位长度图像、文本向量"},{"name":"ᵀ","meaning":"转置向量以便与另一向量做点积","evidence":"上标 ᵀ 表示转置"},{"name":"τ","meaning":"控制候选分布尖锐程度的温度","evidence":"τ 是温度，用来控制候选概率分布的尖锐程度"}]},{"id":"clip-symmetric-cross-entropy","section":3,"formulaIndex":1,"symbols":[{"name":"L","meaning":"图到文与文到图损失的算术平均","evidence":"L 是两方向损失的算术平均"},{"name":"CE","meaning":"在对应候选方向选择真配对的交叉熵","evidence":"CE_image→text 是每张图在全部文本中选中配对文本的平均交叉熵"}]}],"sectionContracts":[{"section":1,"definition":{"answer":"CLIP 双编码器分别把图像和文本映射到同一个归一化向量空间。","evidence":"双编码器先各自理解，再在向量空间相遇"},"problem":{"answer":"它把像素与 token 两种不同输入转换成可直接比较的对象。","evidence":"怎样变成可比较对象"},"inputOutput":{"answer":"输入图像 I 和文本 T，输出同维单位长度向量 v 与 t。","evidence":"两个编码器输出同维向量"},"mechanism":{"answer":"独立编码后除以各自 L2 长度，使点积等于余弦相似度。","evidence":"除以长度会把向量变成单位长度"},"interpretation":{"answer":"较大点积表示模型认为图文在训练关系中更匹配，可用于检索排序。","evidence":"点积就等于余弦相似度"},"boundary":{"answer":"独立编码便于离线索引，却在打分前缺少 token 与区域深度交互。","evidence":"没有逐 token/区域的深度交互"}},{"section":2,"definition":{"answer":"相似度矩阵包含 batch 中每张图与每段文本的全部两两匹配分数。","evidence":"一个 batch 自动形成 N×N 个图文组合"},"problem":{"answer":"它让 N 个真配对同时生成正样本和批内候选负样本。","evidence":"两对真配对为什么同时产生两对负样本"},"inputOutput":{"answer":"输入 N 个图向量、N 个文本向量和 τ，输出 N×N logits。","evidence":"会形成 N 行图像乘 N 列文本"},"mechanism":{"answer":"每个单位图向量与每个单位文向量点积再除温度形成矩阵。","evidence":"vᵢᵀtⱼ 是点积"},"interpretation":{"answer":"对角线是采集正配对，非对角线按标准目标参与负对竞争。","evidence":"矩阵对角线是采集到的正配对"},"boundary":{"answer":"非对角线不保证真负例，batch 变大时语义同类假负例也会增加。","evidence":"假负样本”也会增加"}},{"section":3,"definition":{"answer":"CLIP 用图到文和文到图两个方向的交叉熵共同对齐共享空间。","evidence":"同时做图找文和文找图"},"problem":{"answer":"它防止只优化一个检索方向而令另一侧结构较弱。","evidence":"为什么损失需要按行、按列各算一次"},"inputOutput":{"answer":"输入图文 logits 矩阵，输出行方向、列方向概率和平均损失 L。","evidence":"图到文对每一行做 softmax"},"mechanism":{"answer":"每行让图选择真文本，每列让文本选择真图，两项交叉熵取平均。","evidence":"文到图则按列竞争"},"interpretation":{"answer":"本例图到文真配对概率接近一，说明行方向区分很强且损失较小。","evidence":"I₂ 选 T₂ 的概率"},"boundary":{"answer":"小温度会强化困难负对，也会在弱配对噪声下强记错误。","evidence":"过尖也会强迫模型记住错误"}},{"section":4,"definition":{"answer":"共享空间是图文编码器只在相似度矩阵处交汇的联合表示空间。","evidence":"正配对沿对角线形成共享空间"},"problem":{"answer":"该图展示训练怎样同时移动两侧向量以提高真配对相似度。","evidence":"训练究竟移动了哪些向量"},"inputOutput":{"answer":"输入猫狗图文向量，输出含对角真配对高分的相似度矩阵。","evidence":"猫图 / 狗图"},"mechanism":{"answer":"对称损失拉高对角线配对分数并压低非对角候选。","evidence":"拉高对角线，压低非对角线"},"interpretation":{"answer":"矩阵对角高说明采集图文在该 batch 中相互可检索。","evidence":"使真配对在共享空间靠近"},"boundary":{"answer":"图示只反映全局向量关系，不证明词与区域已形成细粒度对齐。","evidence":"只在相似度矩阵处交汇"}},{"section":5,"definition":{"answer":"零样本分类把预先声明的类别写成文本并编码为类别原型。","evidence":"零样本分类把类别写成文本原型"},"problem":{"answer":"它无需训练新分类头即可在候选类别集合中为图像选择标签。","evidence":"没有训练新的分类头"},"inputOutput":{"answer":"输入待测图和类别文本模板，输出图与各文本原型的相似度及类别。","evidence":"与全部文本原型计算相似度"},"mechanism":{"answer":"编码并归一化多个模板，汇成原型，再对相似度 softmax 或取最大。","evidence":"多个模板可平均成类别原型"},"interpretation":{"answer":"最高相似原型表示在已声明闭集候选中模型最偏向该类。","evidence":"在预先声明的类别集合中"},"boundary":{"answer":"它不是自动发现任意标签，模板、语言、温度和候选集都会改变结果。","evidence":"不是模型凭空发现所有可能标签"}},{"section":6,"definition":{"answer":"双编码器检索独立预编码候选，交叉编码器联合处理查询与每个候选。","evidence":"检索效率来自独立编码"},"problem":{"answer":"它权衡百万候选高吞吐召回与细粒度关系判断能力。","evidence":"复杂关系查询却容易失败"},"inputOutput":{"answer":"输入查询文本和图库，输出 ANN 候选列表及可选精排顺序。","evidence":"找出与查询向量最接近的一小批候选"},"mechanism":{"answer":"CLIP 先按全局向量召回，交叉编码器再用 token 区域交互精排。","evidence":"先用 CLIP 高召回"},"interpretation":{"answer":"可离线建索引表示高召回高吞吐，逐候选联合计算换取更细关系判断。","evidence":"每个候选都需联合计算"},"boundary":{"answer":"ANN 是近似搜索会有召回损失，交叉编码器难以对全库逐项运行。","evidence":"不逐一精确扫描全部图库"}},{"section":7,"definition":{"answer":"组合理解要求模型区分对象相同但角色、数量、方位或否定不同的描述。","evidence":"对象共现不等于关系、计数与否定理解"},"problem":{"answer":"它揭示全局主题相似可能掩盖主客体和谓词错误。","evidence":"狗追人”和“人追狗”"},"inputOutput":{"answer":"输入仅改变关系属性的图文最小对照，输出成对排序正确率。","evidence":"只交换主客体、数量、方位或否定"},"mechanism":{"answer":"保持其他统计一致并只改变目标关系，隔离模型是否真正利用该关系。","evidence":"保持其他词与图像统计一致"},"interpretation":{"answer":"总体 Recall 高但 pairwise accuracy 低表示模型主要依赖对象共现。","evidence":"报告 pairwise accuracy"},"boundary":{"answer":"高相似度不是逻辑蕴含，不能证明描述中每个谓词都获图像支持。","evidence":"高相似度不是蕴含关系"}},{"section":8,"definition":{"answer":"弱图文配对使用网页替代文本、标题或邻近文字提供开放词汇监督。","evidence":"弱配对数据同时带来规模与噪声"},"problem":{"answer":"它以低标注成本扩展规模，却引入错配、偏见、隐私和评测污染。","evidence":"既有价值又危险"},"inputOutput":{"answer":"输入网页图像和周边文本，输出经来源、去重、许可与覆盖治理的配对集。","evidence":"alt-text、标题和邻近文字"},"mechanism":{"answer":"人工抽样、去重、群体语言切片和授权删除链共同控制风险。","evidence":"来源、授权、删除链路"},"interpretation":{"answer":"近重复跨训练测试会虚高迁移成绩，强过滤又可能删掉少数语境。","evidence":"过滤过强则可能删除少数语言和文化语境"},"boundary":{"answer":"海量文本不等于准确描述图像，网页文字可能只描述页面或广告。","evidence":"可能描述页面而非图像"}},{"section":9,"definition":{"answer":"CLIP 分数是图像与文本全局表示的匹配相似度，而非通用质量分。","evidence":"不是通用图像质量或安全裁判"},"problem":{"answer":"它防止用单一可被投机的相似度替代视觉质量、安全和人类偏好。","evidence":"为什么仍可能是一张坏图"},"inputOutput":{"answer":"输入生成图与提示，输出相似度；完整评测另输出质量多样性关系安全指标。","evidence":"生成评估至少分开测"},"mechanism":{"answer":"水印、大字、背景或对抗纹理可提高全局匹配而不修复真实图像缺陷。","evidence":"相似度可被大字、水印、典型背景和对抗纹理提高"},"interpretation":{"answer":"CLIP 高分只支持提示相关性证据，不能推出解剖正确、真实或安全。","evidence":"却忽略解剖错误、事实矛盾"},"boundary":{"answer":"高影响判断必须由独立模型和人工样本校验，不能只用一个嵌入分数。","evidence":"高影响判断不得只靠一个嵌入分数"}}]},"html":"\n        <div class=\"dd-goals\"><b>读完你应该能：</b>手算一张图文相似度矩阵；解释双向对比损失；完成零样本分类流程；诊断提示、组合关系和数据偏差。</div>\n        \n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">1</span>双编码器先各自理解，再在向量空间相遇<span class=\"dd-badge math\">架构</span></h2><p class=\"dd-lead\">像素矩阵和 token 序列怎样变成可比较对象？</p><div class=\"dd-formula\">vᵢ=f<sub>img</sub>(Iᵢ)/‖f<sub>img</sub>(Iᵢ)‖，　tⱼ=f<sub>txt</sub>(Tⱼ)/‖f<sub>txt</sub>(Tⱼ)‖</div><p><b>符号说明：</b><code>Iᵢ</code> 是第 i 张图像，<code>f_img</code> 是图像编码器，<code>vᵢ</code> 是归一化后的图像向量；<code>Tⱼ</code> 是第 j 段文本，<code>f_txt</code> 是文本编码器，<code>tⱼ</code> 是归一化后的文本向量。双竖线 <code>‖·‖</code> 表示向量长度，除以长度会把向量变成单位长度。</p><p>两个编码器输出同维向量并做 L2 归一化，点积就等于余弦相似度。图像与文本可离线分别编码，检索时只做向量比较；代价是它们在打分前没有逐 token/区域的深度交互。</p><div class=\"dd-note\"><b>贯穿例子：</b>batch 有两对数据：I₁=猫图配 T₁“a cat”，I₂=狗图配 T₂“a dog”。归一化后的相似度矩阵为 [[0.8,0.2],[0.3,0.7]]。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">2</span>一个 batch 自动形成 N×N 个图文组合<span class=\"dd-badge math\">相似度矩阵</span></h2><p class=\"dd-lead\">两对真配对为什么同时产生两对负样本？</p><div class=\"dd-formula\">Sᵢⱼ=vᵢᵀtⱼ/τ</div><p><b>式中：</b><code>Sᵢⱼ</code> 是第 i 张图与第 j 段文本送入 softmax 前的匹配分数；<code>vᵢ</code> 和 <code>tⱼ</code> 是单位长度图像、文本向量，上标 <code>ᵀ</code> 表示转置，因此 <code>vᵢᵀtⱼ</code> 是点积；<code>τ</code> 是温度，用来控制候选概率分布的尖锐程度。<code>N</code> 是当前 batch 的真图文对数量，所以会形成 N 行图像乘 N 列文本。</p><p>矩阵对角线是采集到的正配对，非对角线在标准 CLIP 目标中视作负对。对 τ=0.1，原相似度 [[0.8,0.2],[0.3,0.7]] 变为 logits [[8,2],[3,7]]。batch 越大，候选越多，但语义相同却未配对的“假负样本”也会增加。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th></th><th>T₁ 猫</th><th>T₂ 狗</th></tr></thead><tbody><tr><td>I₁ 猫</td><td><b>0.8 正对</b></td><td>0.2 负对</td></tr><tr><td>I₂ 狗</td><td>0.3 负对</td><td><b>0.7 正对</b></td></tr></tbody></table></div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">3</span>CLIP 同时做图找文和文找图<span class=\"dd-badge math\">逐步演算</span></h2><p class=\"dd-lead\">为什么损失需要按行、按列各算一次？</p><p>沿用上一节 logits [[8,2],[3,7]]。图到文对每一行做 softmax：I₁ 选 T₁ 的概率 e⁸/(e⁸+e²)≈<b>0.9975</b>；I₂ 选 T₂ 的概率 e⁷/(e³+e⁷)≈<b>0.9820</b>。文到图则按列竞争，确保文本也能找回图像。</p><div class=\"dd-formula\">L=(CE<sub>image→text</sub>+CE<sub>text→image</sub>)/2</div><p><b>公式含义：</b><code>CE_image→text</code> 是每张图在全部文本中选中配对文本的平均交叉熵，<code>CE_text→image</code> 是每段文本在全部图像中选中配对图像的平均交叉熵；<code>L</code> 是两方向损失的算术平均。交叉熵会对正确配对概率取负对数，所以本例两个行概率越接近 1，图到文损失越小。</p><p>只做单向目标可能让一侧检索结构较弱。温度越小，softmax 越尖锐、困难负对贡献越大；若配对噪声高，过尖也会强迫模型记住错误。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>方向</th><th>查询</th><th>候选竞争</th></tr></thead><tbody><tr><td>图→文</td><td>一张图</td><td>batch 内全部文本</td></tr><tr><td>文→图</td><td>一段文字</td><td>batch 内全部图像</td></tr></tbody></table></div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">4</span>原创图：正配对沿对角线形成共享空间<span class=\"dd-badge intuition\">可视化</span></h2><p class=\"dd-lead\">训练究竟移动了哪些向量？</p><figure class=\"dd-fig\"><svg viewBox=\"0 0 735 310\" role=\"img\" aria-label=\"图像文本双编码器与二乘二相似度矩阵\"><defs><marker id=\"clpa\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#788293\"/></marker></defs><rect x=\"25\" y=\"50\" width=\"120\" height=\"55\" rx=\"8\" fill=\"#21252d\" stroke=\"#65a6d9\"/><text x=\"85\" y=\"82\" text-anchor=\"middle\" class=\"svg-t\">猫图 / 狗图</text><rect x=\"25\" y=\"195\" width=\"120\" height=\"55\" rx=\"8\" fill=\"#21252d\" stroke=\"#d3a05a\"/><text x=\"85\" y=\"227\" text-anchor=\"middle\" class=\"svg-t\">“猫” / “狗”</text><path d=\"M145,78 L240,108\" stroke=\"#788293\" marker-end=\"url(#clpa)\"/><path d=\"M145,222 L240,192\" stroke=\"#788293\" marker-end=\"url(#clpa)\"/><rect x=\"245\" y=\"70\" width=\"145\" height=\"72\" rx=\"9\" fill=\"#21252d\" stroke=\"#65a6d9\"/><text x=\"318\" y=\"98\" text-anchor=\"middle\" class=\"svg-t\">图像编码器</text><text x=\"318\" y=\"121\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">归一化 v₁,v₂</text><rect x=\"245\" y=\"168\" width=\"145\" height=\"72\" rx=\"9\" fill=\"#21252d\" stroke=\"#d3a05a\"/><text x=\"318\" y=\"196\" text-anchor=\"middle\" class=\"svg-t\">文本编码器</text><text x=\"318\" y=\"219\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">归一化 t₁,t₂</text><path d=\"M390,106 L475,135\" stroke=\"#788293\" marker-end=\"url(#clpa)\"/><path d=\"M390,204 L475,174\" stroke=\"#788293\" marker-end=\"url(#clpa)\"/><rect x=\"480\" y=\"82\" width=\"210\" height=\"145\" rx=\"10\" fill=\"#21252d\" stroke=\"#8b76bd\"/><text x=\"585\" y=\"108\" text-anchor=\"middle\" class=\"svg-t\">相似度矩阵 S/τ</text><rect x=\"525\" y=\"125\" width=\"62\" height=\"38\" fill=\"#315d54\"/><rect x=\"590\" y=\"125\" width=\"62\" height=\"38\" fill=\"#343943\"/><rect x=\"525\" y=\"166\" width=\"62\" height=\"38\" fill=\"#343943\"/><rect x=\"590\" y=\"166\" width=\"62\" height=\"38\" fill=\"#315d54\"/><text x=\"556\" y=\"150\" text-anchor=\"middle\" class=\"svg-t\">8</text><text x=\"621\" y=\"150\" text-anchor=\"middle\" class=\"svg-t\">2</text><text x=\"556\" y=\"191\" text-anchor=\"middle\" class=\"svg-t\">3</text><text x=\"621\" y=\"191\" text-anchor=\"middle\" class=\"svg-t\">7</text><text x=\"585\" y=\"256\" text-anchor=\"middle\" class=\"svg-t\">拉高对角线，压低非对角线</text></svg><figcaption>图 1　双编码器只在相似度矩阵处交汇；训练信号同时更新两侧，使真配对在共享空间靠近。</figcaption></figure></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">5</span>零样本分类把类别写成文本原型<span class=\"dd-badge eng\">迁移</span></h2><p class=\"dd-lead\">没有训练新的分类头，怎样预测“猫”还是“狗”？</p><ol><li>把候选类写成“a photo of a cat/dog”等模板。</li><li>分别编码并归一化，多个模板可平均成类别原型。</li><li>编码待测图像，与全部文本原型计算相似度。</li><li>在预先声明的类别集合中 softmax 或取最大值。</li></ol><p>这是闭集候选上的零样本分类，不是模型凭空发现所有可能标签。类别名称、语言、模板、温度和候选集合都会改变结果；应在验证集选择模板并冻结后再测试。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">6</span>检索效率来自独立编码，精排能力也因此受限<span class=\"dd-badge eng\">系统</span></h2><p class=\"dd-lead\">为什么百万图库可预编码，而复杂关系查询却容易失败？</p><p>图库向量可提前建 ANN（近似最近邻）索引：它用索引结构快速找出与查询向量最接近的一小批候选，而不逐一精确扫描全部图库。查询文本只编码一次，因此双编码器吞吐高。cross-encoder（交叉编码器）则让文本 token 与图像区域在同一模型内交互，关系判断更细，但每个候选都需联合计算。常见系统先用 CLIP 高召回，再用跨模态交叉编码器精排。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>结构</th><th>离线索引</th><th>交互深度</th><th>用途</th></tr></thead><tbody><tr><td>双编码器 CLIP</td><td>可</td><td>全局向量</td><td>召回、零样本</td></tr><tr><td>Cross-encoder</td><td>难</td><td>token/区域交互</td><td>小候选精排</td></tr></tbody></table></div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">7</span>对象共现不等于关系、计数与否定理解<span class=\"dd-badge intuition\">组合边界</span></h2><p class=\"dd-lead\">“狗追人”和“人追狗”为何可能得到近似向量？</p><p>两句包含相同对象与动作词，网页配对又常是粗标题；全局对比目标只需让正确主题胜过 batch 内其他文本，不一定解析角色顺序。“没有狗”“两只狗”“狗在桌下”也可能被对象词主导。</p><p>应构造最小对照：只交换主客体、数量、方位或否定，保持其他词与图像统计一致；报告 pairwise accuracy，而非只看总体 Recall。</p><div class=\"dd-note warn\"><b>高相似度不是蕴含关系。</b>它不证明描述中每个谓词都被图像支持。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">8</span>弱配对数据同时带来规模与噪声<span class=\"dd-badge eng\">数据</span></h2><p class=\"dd-lead\">网页替代文本为什么既有价值又危险？</p><p>alt-text、标题和邻近文字提供海量开放词汇监督，但可能描述页面而非图像，包含广告、刻板印象、身份误标和个人信息。近重复内容还会让训练与评测泄漏。过滤过强则可能删除少数语言和文化语境。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>风险</th><th>检查</th></tr></thead><tbody><tr><td>错配/弱描述</td><td>人工抽样、噪声鲁棒训练</td></tr><tr><td>社会偏见</td><td>人群×职业×语言切片</td></tr><tr><td>重复与污染</td><td>图像/文本近重复去重</td></tr><tr><td>隐私与许可</td><td>来源、授权、删除链路</td></tr></tbody></table></div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">9</span>CLIP 分数不是通用图像质量或安全裁判<span class=\"dd-badge eng\">失效边界</span></h2><p class=\"dd-lead\">生成图与提示相似度高，为什么仍可能是一张坏图？</p><p>相似度可被大字、水印、典型背景和对抗纹理提高，却忽略解剖错误、事实矛盾、审美、版权和安全。用 CLIP 作生成奖励会诱发 reward hacking；做过滤器会产生群体差异与规避空间。</p><p>生成评估至少分开测提示对齐、视觉质量、多样性、关系/文字准确、安全与人类偏好，并用独立模型和人工样本校验。高影响判断不得只靠一个嵌入分数。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"reference\"><h2><span class=\"dd-n\">10</span>常见误区与学习路线<span class=\"dd-badge intuition\">误区与依赖</span></h2><p class=\"dd-lead\">把 CLIP 看成跨模态检索度量，而不是视觉事实验证器。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>误区</th><th>更准确的理解</th></tr></thead><tbody><tr><td>共享空间表示真正理解全部语义</td><td>优化的是配对相对排序</td></tr><tr><td>非对角线都是真负样本</td><td>可能存在语义同类或多描述</td></tr><tr><td>零样本完全无需设计</td><td>模板与类别集合影响原型</td></tr><tr><td>相似度高表示描述完全正确</td><td>对象共现可掩盖关系错误</td></tr><tr><td>CLIP 分数等于图像质量</td><td>需多维独立评估</td></tr></tbody></table></div><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>层级</th><th>依赖与延伸</th></tr></thead><tbody><tr><td>先修</td><td>嵌入、softmax、对比学习</td></tr><tr><td><b>本页核心</b></td><td>双编码器、对称损失、文本原型</td></tr><tr><td>系统</td><td>向量数据库、重排、图像生成</td></tr><tr><td>评测</td><td>组合泛化、公平、数据治理</td></tr></tbody></table></div></section>\n        <section class=\"dd-sec\" data-section-role=\"synthesis\"><h2><span class=\"dd-n\">11</span>把因果链连起来<span class=\"dd-badge intuition\">综合</span></h2><p class=\"dd-lead\">这个概念怎样从问题一路连接到可验证的实践？</p><ol class=\"dd-chain\"><li>收集并治理图文配对</li><li>双编码器产生归一化向量</li><li>构造批内相似度矩阵</li><li>双向交叉熵对齐空间</li><li>文本原型或 ANN 完成迁移</li><li>用最小对照与群体切片限定用途</li></ol></section>\n        <section class=\"dd-sec\" data-section-role=\"assessment\"><h2><span class=\"dd-n\">12</span>误区与自测<span class=\"dd-badge intuition\">自测</span></h2><p class=\"dd-lead\">你能否不用背术语，解释它的机制、边界与验证方法？</p><div class=\"dd-quiz\"><ol><li>例子中 I₁ 选 T₁ 的概率约多少？</li><li>为什么损失要双向计算？</li><li>零样本分类的类别从哪里来？</li><li>双编码器为何适合大规模检索？</li><li>CLIP 高分为何不证明描述完整正确？</li><li>假设“CLIP：用图文对比把两种模态对齐到同一空间”在离线示例上表现正常、上线后核心结果却下降，你会怎样按输入、内部变换、输出反馈和适用边界定位问题？</li><li>如何为“CLIP：用图文对比把两种模态对齐到同一空间”设计一个最小对照实验，证明观察到的改善来自核心机制，而不是数据、提示、权限或评测口径同时变化？</li></ol></div><details class=\"dd-answers\"><summary>参考答案</summary><ol><li>τ=0.1时 logits 为8和2，概率约0.9975。</li><li>同时训练图找文与文找图的检索结构。</li><li>来自用户预先写出的文本类别原型及模板。</li><li>候选图文可独立预编码并建立向量索引。</li><li>全局相似度可能由对象共现主导，忽略关系、数量和否定。</li><li>先保存同一失败样本及环境，确认输入、权限和前置条件没有漂移；再记录关键中间状态，检查机制是否按本页描述完成变换；随后把原始输出与独立指标、人工终验对照；最后用边界样例和对照实验复测。只有定位到首次偏离预期的环节，才能判断应修改数据、机制、评测还是使用边界。</li><li>固定数据、模型版本、提示、权限、预算和评测，只改变一个与核心机制直接相关的因素，并在多个样本与随机种子上重复；同时保存中间状态和失败样本。若差异只在目标因素变化时稳定出现，才支持机制解释，否则应继续排查混杂变量。</li></ol></details></section>\n        <div class=\"dd-src\"><b>资料来源与改编说明</b><ul><li><a href=\"https://arxiv.org/abs/2103.00020\" target=\"_blank\" rel=\"noopener\">Learning Transferable Visual Models From Natural Language Supervision</a>：CLIP 双编码器与零样本迁移</li><li><a href=\"https://arxiv.org/abs/2102.05918\" target=\"_blank\" rel=\"noopener\">Scaling Up Visual and Vision-Language Representation Learning With Noisy Text Supervision</a>：ALIGN 弱文本监督</li><li><a href=\"https://arxiv.org/abs/2303.15343\" target=\"_blank\" rel=\"noopener\">Sigmoid Loss for Language Image Pre-Training</a>：SigLIP 配对损失</li><li><a href=\"https://arxiv.org/abs/2204.03162\" target=\"_blank\" rel=\"noopener\">Winoground</a>：组合关系诊断</li><li><a href=\"https://arxiv.org/abs/1908.04913\" target=\"_blank\" rel=\"noopener\">FairFace</a>：视觉公平切片背景</li></ul><div class=\"dd-src-date\">访问日期：2026-07-22</div></div>"};
